tool_calls:
awk '
function trim(s){gsub(/^[ \t]+|[ \t]+$/,"",s);return s}
/^[ \t]*[;#]/ || /^[ \t]*$/ {next}
/^[ \t]*\[.*\][ \t]*$/ {sec=trim($0); gsub(/^\[|\]$/,"",sec); if(!(sec in seen)){seen[sec]=1; so[++ns]=sec}; next}
{ i=index($0,"="); if(!i) next; k=trim(substr($0,1,i-1)); v=trim(substr($0,i+1));
  key=sec SUBSEP k; if(!(key in val)){ko[sec,++nk[sec]]=k}; val[key]=v }
END{ for(s=1;s<=ns;s++){ sec=so[s]; if(s>1)print ""; print "[" sec "]";
  for(j=1;j<=nk[sec];j++){k=ko[sec,j]; print k "=" val[sec,k]} } }
' /config/defaults.ini /config/custom.ini > /config/merged.ini; cat /config/merged.ini

